<?php

namespace App\Domain\Access;

use App\Models\User;
use Carbon\CarbonImmutable;
use Illuminate\Auth\Passwords\PasswordBroker;
use Illuminate\Auth\Passwords\PasswordBrokerManager;
use Illuminate\Auth\Passwords\TokenRepositoryInterface;
use Illuminate\Support\Facades\DB;
use LogicException;

/**
 * The one-time link broker (ADR-004 item 4; SECURITY_MODEL SEC-ACC-04 to
 * SEC-ACC-06; SCHEMA section 5.1, `password_reset_tokens`), an Access service
 * on the token repository of Laravel's password broker. A link's token is
 * random, generated by the repository and stored only as an Argon2id hash;
 * an account has at most one link, and a new one replaces the old one; a
 * link expires 60 minutes after it is created (config auth.passwords.users)
 * and is consumed once (App\Actions\Access\ConsumeLink).
 *
 * A link names its account by the internal identity, and its token is
 * checked only against that account's current link: the repository keys
 * tokens by email, so the caller always passes the account it has locked,
 * never an email from a request. The issuing commands — OP-01 (TASK-010),
 * RC-35 and RC-41 (TASK-011) — call issue() inside their transaction, under
 * the target account's lock, and RC-42, deactivation, anonymization and an
 * email change call revoke() the same way; the application never emails a
 * link (D-049). Each of these methods runs inside the caller's transaction.
 */
final class OneTimeLinks
{
    /** The longest token the consumption accepts; the repository makes 64 characters. */
    public const int TOKEN_MAX = 128;

    private readonly TokenRepositoryInterface $tokens;

    public function __construct(PasswordBrokerManager $brokers)
    {
        $broker = $brokers->broker('users');

        if (! $broker instanceof PasswordBroker) {
            throw new LogicException('The one-time links use the password broker "users" of config/auth.php.');
        }

        $this->tokens = $broker->getRepository();
    }

    /**
     * Creates the account's link, replacing any earlier one, and returns its
     * token in plain text, which the caller hands over once (SEC-ACC-05) and
     * never logs, stores or audits.
     */
    public function issue(User $locked): string
    {
        self::requireTransaction();

        return $this->tokens->create($locked);
    }

    /**
     * Whether a link was created for the account in the last 60 seconds, the
     * broker's throttle (SECURITY_MODEL section 11).
     */
    public function recentlyIssued(User $account): bool
    {
        return $this->tokens->recentlyCreatedToken($account);
    }

    /**
     * When the account's current link expires, or null when it has none in
     * force: an expired row is no link (UXP-604; RC-42).
     */
    public function activeUntil(User $account): ?CarbonImmutable
    {
        $created = DB::table('password_reset_tokens')->where('email', $account->getEmailForPasswordReset())->value('created_at');

        if (! is_string($created)) {
            return null;
        }

        $until = CarbonImmutable::parse($created)->addMinutes(self::minutes());

        return $until->isFuture() ? $until : null;
    }

    /**
     * How long a link stays valid after it is created (config auth.passwords.users).
     */
    public static function minutes(): int
    {
        return config()->integer('auth.passwords.users.expire');
    }

    /**
     * Whether the token is the account's current link and has not expired.
     */
    public function matches(User $locked, #[\SensitiveParameter] string $token): bool
    {
        self::requireTransaction();

        return $token !== '' && strlen($token) <= self::TOKEN_MAX && $this->tokens->exists($locked, $token);
    }

    /**
     * Revokes the account's link, if it has one: its row is deleted.
     */
    public function revoke(User $locked): void
    {
        self::requireTransaction();

        $this->tokens->delete($locked);
    }

    /**
     * The address of the link page with the account's internal identity and
     * the token in the fragment, which browsers never send to the server
     * (ROUTE_CONTRACTS RP-002; SEC-ACC-05).
     */
    public static function url(User $account, #[\SensitiveParameter] string $token): string
    {
        return route('password.link').'#u='.$account->id.'&t='.rawurlencode($token);
    }

    private static function requireTransaction(): void
    {
        if (DB::transactionLevel() === 0) {
            throw new LogicException('A one-time link is issued, checked and revoked inside the transaction that holds its account lock (RACE-20).');
        }
    }
}
